=== ValidatePasteClaims
package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.List;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: each non-blank line is name,amount,date,note (the note may hold commas and may be absent; a blank
 *  date takes the sheet's entry date, else its today), read by the claim form's rules. A note (its surrounding spaces removed) ending
 *  in ` #<reference>` gives the claim that reference, and that part is not part of the note. A line with no name, or a paste with no
 *  lines, is refused. */
public class ValidatePasteClaims {
    public void validate(@RequestBody PasteClaimsRequest request, Out<PastedLines> pasted) throws InvalidClaimException {
        String text = request == null || request.text() == null ? "" : request.text();
        String by = request == null || request.by() == null ? "" : request.by().trim();
        List<PastedLine> lines = new ArrayList<>();
        for (String line : text.split("\\r?\\n")) {
            if (line.isBlank()) {
                continue;
            }
            String[] fields = line.split(",", 4);
            String name = fields[0].trim();
            if (name.isEmpty()) {
                throw new InvalidClaimException("Each line must name a person");
            }
            String note = fields.length > 3 ? fields[3].trim() : "";
            String ref = "";
            int hash = note.lastIndexOf(" #");
            if (hash >= 0 && !note.substring(hash + 2).isBlank()) {
                ref = note.substring(hash + 2);
                note = note.substring(0, hash);
            }
            ClaimRequest claim = new ClaimRequest(fields.length > 1 ? fields[1] : "", fields.length > 2 ? fields[2] : "",
                    note, "", by, ref, null);
            lines.add(new PastedLine(name, ClaimValues.from(claim)));
        }
        if (lines.isEmpty()) {
            throw new InvalidClaimException("Paste at least one line of name,amount,date,note");
        }
        pasted.set(new PastedLines(lines, by));
    }
}
=== CheckPastedClaims
package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Checks every pasted line before any is added: its person must be on the sheet (names compared as names are, case
 *  and outer spaces ignored) and its claim must keep the rules of adding a claim (see ClaimRules), its reference
 *  not repeating one on an earlier line (case ignored). Any failing line refuses the whole paste. */
public class CheckPastedClaims {
    public void check(@PathVariable("sheetId") String sheetId, @Val PastedLines pasted, PersonRepository people,
            SettingRepository settings, PeriodRepository periods, ClaimRepository claims, HolidayRepository holidays,
            Out<PastedClaims> checked)
            throws InvalidClaimException {
        String sheet = sheetId.trim();
        List<PastedClaim> all = new ArrayList<>();
        Set<String> refs = new HashSet<>();
        for (PastedLine line : pasted.lines()) {
            Person person = people.findByName(sheet, line.name());
            if (person == null) {
                throw new InvalidClaimException("No person named " + line.name() + " on the sheet");
            }
            String ref = line.values().ref();
            if (ref != null && !refs.add(ClaimValues.refKey(ref))) {
                throw new InvalidClaimException("The reference " + ref + " is pasted more than once");
            }
            all.add(new PastedClaim(person, line.values(), ClaimRules.check(person, line.values(), settings, periods, claims, holidays)));
        }
        checked.set(new PastedClaims(all));
    }
}
=== AddPastedClaims
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Adds the checked claims as DRAFTs in the order pasted, each as AddClaim adds one, writing CLAIM_ADDED for each (with ref=<reference> at its end when it has one; and LATE_ENTRY after it for a late entry) and
 *  then the figures the paste moved (see Rollup). */
public class AddPastedClaims {
    public void add(@PathVariable("sheetId") String sheetId, @Val PastedClaims checked, @Val PastedLines pasted,
            @Val RollupBefore before, ClaimRepository claims, SettingRepository settings, PeriodRepository periods, ClaimLog log, Rollup rollup,
            Audit audit, Out<PasteClaimsResult> result) {
        List<String> lines = new ArrayList<>();
        for (PastedClaim c : checked.claims()) {
            LocalDate date = c.checked().date();
            String sheet = c.person().sheetId();
            Claim added = claims.add(sheet, c.person().id(), c.values().amount(), date, c.values().note(),
                    c.checked().corrects(), c.values().ref(), c.values().tags(), c.checked().dueBy(), c.checked().terms());
            log.write(added, pasted.by());
            lines.add("CLAIM_ADDED sheet=" + added.sheetId() + " by=" + pasted.by() + " person=" + c.person().name()
                    + " amount=" + added.amount().toPlainString() + " date=" + added.date()
                    + (added.ref() == null ? "" : " ref=" + added.ref()));
            if (periods.softClosedOn(sheet, c.checked().dueBy())) {
                claims.markLateEntry(added);
                lines.add("LATE_ENTRY sheet=" + added.sheetId() + " by=" + pasted.by() + " person=" + c.person().name()
                        + " amount=" + added.amount().toPlainString() + " date=" + added.date());
            }
        }
        lines.forEach(audit::record);
        rollup.record(sheetId.trim(), pasted.by(), before);
        result.set(new PasteClaimsResult(checked.claims().size()));
    }
}
