import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PeopleHead, PersonRow } from '../../slots/defs/personRow';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { useClaims } from '../claims/claims';
import { plusDays } from '../overdue/late';
import { usePeople, type Person } from '../people/people';
import { useSheetToday } from '../session/session';
import { equalShares, sharedSum, sum } from '../rates/rates';
import { patronsKey, usePatrons, type Patron } from './patrons';

function PatronsHead() {
  return (
    <>
      <th>Patrons</th>
      <th>Backing</th>
      <th />
    </>
  );
}

/** A person's patrons with their shares (100.00 split equally in the order they were named, the remainder to the
 *  first; shown as "<name> <share>", sorted by name), their backing (over the patrons, each patron's figure — the dues
 *  fixed when settled of their SETTLED claims dated within the 90 days up to and including the sheet's today, added
 *  up — times their share / 100, added up and rounded half to even; 0.00 with none), and the picker that names another person on the sheet as a patron. A refused add shows the row's
 *  patron error. */
function PersonPatrons({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const people = usePeople(sheetId);
  const patrons = usePatrons(sheetId);
  const claims = useClaims(sheetId);
  const today = useSheetToday(sheetId);
  const queryClient = useQueryClient();
  const [chosen, setChosen] = useState('');

  const submit = useSubmitOnce();
  const add = useMutation({
    mutationFn: (patronId: number) =>
      postJson<Patron>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${person.id}/patrons`, { patronId, by: user }),
    onSuccess: () => {
      setChosen('');
      return queryClient.invalidateQueries({ queryKey: patronsKey(sheetId) });
    },
    onSettled: submit.end,
  });

  const mine = (patrons.data ?? [])
    .filter((p) => p.personId === person.id)
    .map((p) => people.data?.find((q) => q.id === p.patronId))
    .filter((p): p is Person => p !== undefined);
  const shares = equalShares(mine.length);
  const names = mine
    .map((p, i) => ({ name: p.name, share: shares[i] }))
    .sort((a, b) => a.name.localeCompare(b.name))
    .map((p) => `${p.name} ${p.share}`);
  const since = today === '' ? '' : plusDays(today, -89);
  const settled = (claims.data ?? []).filter((c) => c.status === 'SETTLED' && c.date >= since && c.date <= today);
  const backing = sharedSum(
    mine.map((p, i) => ({
      value: sum(settled.filter((c) => c.personId === p.id).map((c) => c.due ?? 'n/a')),
      pct: shares[i],
    })),
  );
  const others = (people.data ?? []).filter((p) => p.id !== person.id);

  return (
    <>
      <td data-testid="person-patrons">{names.join(', ')}</td>
      <td data-testid="person-backing">{backing}</td>
      <td>
        <select
          data-testid="person-patron-select"
          value={chosen}
          onChange={(e) => {
            setChosen(e.target.value);
            add.reset();
          }}
        >
          <option value="">Patron…</option>
          {others.map((p) => (
            <option key={p.id} value={String(p.id)}>
              {p.name}
            </option>
          ))}
        </select>{' '}
        <button
          type="button"
          data-testid="person-patron-add"
          disabled={add.isPending}
          onClick={() => {
            if (!submit.begin()) return;
            add.reset();
            add.mutate(Number(chosen)); // nothing chosen: no person 0, so the server refuses it
          }}
        >
          Add patron
        </button>
        {add.isError && <span data-testid="person-patron-error"> Could not add this patron.</span>}
      </td>
    </>
  );
}

export const contributions = [
  PeopleHead.fill({ order: 60, Component: PatronsHead }),
  PersonRow.fill({ order: 60, Component: PersonPatrons }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** That the person `personId` has named `patronId`, another person on the sheet, as a patron. */
export type Patron = { personId: number; patronId: number };

export const patronsKey = (sheetId: string) => ['sheet', sheetId, 'patrons'];

/** Every patron named on the sheet. */
export function usePatrons(sheetId: string) {
  return useQuery({
    queryKey: patronsKey(sheetId),
    queryFn: () => getJson<Patron[]>(`/api/sheets/${encodeURIComponent(sheetId)}/patrons`),
  });
}
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

/** The date this screen shows the sheet as of (yyyy-MM-dd; the `asof` search param, see features/asof), or ''. While
 *  set, every read of a sheet asks for it as it stood then (`asOf`), and every change carries it (the X-As-Of header)
 *  so the server refuses it. */
export function viewAsOf(): string {
  const raw = new URLSearchParams(window.location.search).get('asof') ?? '';
  return /^"?(\d{4}-\d{2}-\d{2})"?$/.exec(raw)?.[1] ?? '';
}

async function send<T>(path: string, init?: RequestInit, now = false): Promise<T> {
  const asOf = now ? '' : viewAsOf();
  if (asOf !== '' && path.startsWith('/api/sheets/')) {
    if ((init?.method ?? 'GET') === 'GET') {
      path = `${path}${path.includes('?') ? '&' : '?'}asOf=${asOf}`;
    } else {
      init = { ...init, headers: { ...(init?.headers as Record<string, string>), 'X-As-Of': asOf } };
    }
  }
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

/** A read; `now` asks for the sheet as it is now, whatever the as-of date (see query/readNow). */
export function getJson<T>(path: string, now = false): Promise<T> {
  return send<T>(path, undefined, now);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

